function buildCandidateRequest(){if(!files.length)throw Error('이미지를 한 장 이상 추가하세요.');const form=new FormData($('#createForm')),[width,height]=String(form.get('resolution')).split('x').map(Number),segments=$$('.segment').map(row=>{const file=files.find(item=>segmentFileKey(item)===row.dataset.key);return{file,prompt:row.querySelector('.segment-prompt').value.trim(),seconds:Number(row.querySelector('.segment-seconds').value),order:Number(row.querySelector('.segment-order').value)}});if(segments.some(item=>!item.prompt))throw Error('모든 이미지에 장면 프롬프트를 입력하세요.');const warnings=segments.filter(item=>item.prompt.length>=500&&item.seconds<5);if(warnings.length&&!confirm(`긴 프롬프트에 비해 구간 시간이 짧습니다.\n\n${warnings.map(item=>`순서 ${item.order}: ${item.prompt.length}자 / ${item.seconds}초`).join('\n')}\n\n후보 영상이 불안정할 수 있습니다. 그대로 후보군을 등록할까요?`))return null;const data={job_name:form.get('job_name'),fps:Number(form.get('fps')),seed:Number(form.get('seed')),width,height,global_prompt:form.get('global_prompt'),candidate_count:Number(form.get('candidate_count')||3),segments:segments.map(({file,...item})=>item)},body=new FormData();body.set('data',JSON.stringify(data));segments.forEach((item,index)=>body.set('image_'+index,item.file));return body}
