const directorBackgroundStatusLabel=status=>({prompt_required:'배경 Prompt 필요',awaiting_background_image:'배경 이미지 필요',image_review_required:'배경 검수 필요',image_changes_required:'배경 수정 필요',ready:'배경 준비 완료'}[status]||status||'상태 없음');
function directorPromptBlock(label,text,emptyMessage='Prompt가 없습니다.'){const value=String(text||'').trim();return`<div class="director-copy-block"><div class="director-copy-head"><b>${directorPromptEscape(label)}</b><button type="button" data-director-copy ${value?'':'disabled'}>복사</button></div>${value?`<pre>${directorPromptEscape(value)}</pre>`:`<p class="director-prompt-warning">${directorPromptEscape(emptyMessage)}</p>`}</div>`}
function bindDirectorCopyButtons(root=document){root.querySelectorAll('[data-director-copy]').forEach(button=>button.onclick=async()=>{try{const text=button.closest('.director-copy-block')?.querySelector('pre')?.textContent||'';await copyTextToClipboard(text);const original=button.textContent;button.textContent='복사됨';setTimeout(()=>button.textContent=original,1200)}catch(error){note(error.message,true)}})}
function renderDirectorPromptClips(){const box=$('#directorPromptClips');if(!box)return;const groups=directorPromptState.backgroundGroups||[];if(!groups.length){box.innerHTML='<span class="muted">배경 그룹 또는 클립이 없습니다.</span>';return}const selectedId=String(directorPromptState.selectedBackgroundId||''),selectedClipId=directorPromptState.selectedDetail?.clip_id||'';box.innerHTML=`<div class="director-background-accordion">${groups.map(group=>{const image=group.image_generation||{},prompt=image.generation_prompt||'',open=String(group.background_id)===selectedId;return`<details class="director-background-row" data-director-background-row="${directorPromptEscape(group.background_id)}" ${open?'open':''}><summary><span class="director-background-row-title"><b>${directorPromptEscape(group.display_name)}</b><small>${directorPromptEscape(group.background_id)}</small></span><span class="director-background-row-meta"><em>${directorPromptEscape(directorBackgroundStatusLabel(image.status))}</em><small>클립 ${(group.clips||[]).length}개</small><i aria-hidden="true"></i></span></summary><div class="director-background-body">${directorPromptBlock('재사용 배경 이미지 생성 Prompt',prompt,'이 배경 그룹의 독립형 배경 생성 Prompt가 아직 없습니다.')}${image.negative_prompt?directorPromptBlock('Background Negative Prompt',image.negative_prompt):''}<p class="director-location-note">${directorPromptEscape(group.lighting||'')} ${directorPromptEscape(group.color_palette||'')}</p><div class="director-prompt-clips">${(group.clips||[]).map(clip=>`<button type="button" class="director-prompt-clip${clip.clip_id===selectedClipId?' is-active':''}" data-director-clip="${directorPromptEscape(clip.clip_id)}"><b>${directorPromptEscape(clip.clip_id)}</b><span>${directorPromptEscape(directorPromptStatusLabel(clip.status))}</span><small>${Number(clip.requested_seconds||0)}초 · 독립 Prompt ${clip.standalone_prompt_count||0}/${clip.segment_count||0} · 승인 ${clip.approved_image_count||0}/${clip.segment_count||0}</small></button>`).join('')||'<span class="muted">연결된 클립 없음</span>'}</div></div></details>`}).join('')}</div>`;box.querySelectorAll('[data-director-background-row]').forEach(row=>row.ontoggle=()=>{const id=row.dataset.directorBackgroundRow;if(row.open){box.querySelectorAll('[data-director-background-row]').forEach(other=>{if(other!==row)other.open=false});directorPromptState.selectedBackgroundId=id;if(directorPromptState.selectedDetail&&!row.querySelector(`[data-director-clip="${CSS.escape(directorPromptState.selectedDetail.clip_id)}"]`)){directorPromptState.selectedDetail=null;renderDirectorPromptDetail(null)}}else if(String(directorPromptState.selectedBackgroundId)===id)directorPromptState.selectedBackgroundId=null});box.querySelectorAll('[data-director-clip]').forEach(button=>button.onclick=()=>selectDirectorPromptClip(button.dataset.directorClip));bindDirectorCopyButtons(box)}
function renderDirectorPromptDetail(detail){const box=$('#directorPromptPreview'),load=$('#directorPromptLoad'),payload=detail?.machine_payload||{},segments=payload.segments||[];if(!detail){box.innerHTML='<div class="director-empty-state"><b>클립을 선택하세요.</b><span>배경 그룹을 펼친 뒤 확인할 클립을 선택하면 Prompt와 이미지를 볼 수 있습니다.</span></div>';load.disabled=true;return}const warnings=[...(detail.warnings||[]),...(detail.errors||[])];box.innerHTML=`<div class="director-detail-head"><div><small>선택한 클립</small><h3>${directorPromptEscape(detail.clip_id)}</h3></div><div class="director-prompt-meta"><span>${directorPromptEscape(directorPromptStatusLabel(detail.status))}</span><span>${Number(detail.requested_seconds||0)}초</span><span>Segment ${segments.length}개</span></div></div>${warnings.length?`<div class="director-prompt-warning">${warnings.map(directorPromptEscape).join('<br>')}</div>`:''}${directorPromptBlock('Global Prompt',payload.global_prompt)}<div class="director-prompt-segments">${segments.map((segment,index)=>{const image=segment.scene_image||{},segmentId=directorPromptEscape(segment.segment_id),references=image.reference_paths||[],notes=image.review_notes||[];return`<details class="director-segment-card" data-director-segment="${segmentId}" ${index===0?'open':''}><summary><span><b>${segmentId}</b><small>${Number(segment.seconds||0)}초 · 순서 ${Number(segment.order||index+1)}</small></span><span class="director-segment-status">검수 ${directorPromptEscape(image.review_status||'pending')}</span></summary><div class="director-segment-body"><aside class="director-segment-media">${image.asset_url?`<img src="${directorPromptEscape(image.asset_url)}?v=${directorPromptEscape(image.actual_sha256||image.sha256||'')}" alt="${segmentId}">`:'<div class="director-prompt-image-missing">매칭된 이미지 없음</div>'}<div class="director-prompt-drop" data-director-drop="${segmentId}"><input type="file" accept=".png,.jpg,.jpeg,.webp,.jfif,image/*" hidden><b>이미지 드롭</b><small>또는 클릭하여 선택</small></div>${references.length?`<div class="director-reference-list"><b>첨부 레퍼런스</b>${references.map(path=>`<code>${directorPromptEscape(path)}</code>`).join('')}</div>`:''}</aside><section class="director-segment-content">${directorPromptBlock('Director Prompt',segment.director_prompt)}${directorPromptBlock('독립형 이미지 생성 Prompt',image.prompt,'이미지 생성 Prompt가 없습니다.')}${image.negative_prompt?directorPromptBlock('Image Negative Prompt',image.negative_prompt):''}${notes.length?`<details class="director-review-notes"><summary>검수·연결 정보 ${notes.length}건</summary><ul>${notes.map(note=>`<li>${directorPromptEscape(note)}</li>`).join('')}</ul></details>`:''}<div class="director-review-actions"><button type="button" data-director-review="approved" data-segment="${segmentId}" ${image.asset_url?'':'disabled'}>이미지 승인</button><button type="button" data-director-review="changes_required" data-segment="${segmentId}" ${image.asset_url?'':'disabled'}>수정 필요</button></div></section></div></details>`}).join('')}</div>${detail.registration_block_reason?`<p class="director-prompt-warning">${directorPromptEscape(detail.registration_block_reason)}</p>`:''}`;load.disabled=!detail.can_register_director;bindDirectorPromptSegmentControls();bindDirectorCopyButtons(box)}
function prepareDirectorPromptDetail(detail){const payload=detail?.machine_payload||{},locationId=payload.location?.location_id||'',group=(directorPromptState.backgroundGroups||[]).find(item=>item.location_id===locationId);for(const segment of payload.segments||[]){const image=segment.scene_image||{},standalone=String(image.generation_prompt||'').trim(),legacy=String(image.prompt||'').trim(),references=image.reference_paths||[],notes=[...(image.review_notes||[])];image.prompt=standalone||legacy;notes.push(group?`배경 그룹: ${group.display_name} (${group.background_id})`:`배경 그룹 미지정: ${locationId||'없음'}`);notes.push(standalone?'독립형 이미지 생성 Prompt 사용 중':'주의: 현재 레거시 Prompt를 표시 중이며 독립형 generation_prompt 재생성이 필요합니다.');if(references.length)notes.push(`첨부할 레퍼런스: ${references.join(', ')}`);image.review_notes=notes;segment.scene_image=image}return detail}
function updateDirectorPromptDetail(detail){detail=prepareDirectorPromptDetail(detail);directorPromptState.selectedDetail=detail;const index=directorPromptState.clips.findIndex(clip=>clip.clip_id===detail.clip_id);if(index>=0)directorPromptState.clips[index]={...directorPromptState.clips[index],status:detail.status,approved_image_count:detail.approved_image_count,can_register_director:detail.can_register_director};renderDirectorPromptClips();renderDirectorPromptDetail(detail)}
async function uploadDirectorPromptSegmentImage(segmentId,file){if(!file||!/\.(png|jpe?g|webp|jfif)$/i.test(file.name))throw Error('PNG, JPG, WEBP 이미지만 매칭할 수 있습니다.');const detail=directorPromptState.selectedDetail,projectId=$('#directorPromptProject').value,body=new FormData();body.set('file',file);const out=await api(`/api/director-prompt-projects/${encodeURIComponent(projectId)}/clips/${encodeURIComponent(detail.clip_id)}/segments/${encodeURIComponent(segmentId)}/image`,{method:'POST',body});updateDirectorPromptDetail(out);note(`${segmentId} 장면 이미지가 매칭되었습니다. 미리보기를 확인하고 승인하세요.`)}
async function reviewDirectorPromptSegmentImage(segmentId,status){const detail=directorPromptState.selectedDetail,projectId=$('#directorPromptProject').value;let reviewNotes=[];if(status==='changes_required'){const message=prompt('수정이 필요한 내용을 입력하세요.','');if(message===null)return;reviewNotes=message.trim()?[message.trim()]:[]}const out=await api(`/api/director-prompt-projects/${encodeURIComponent(projectId)}/clips/${encodeURIComponent(detail.clip_id)}/segments/${encodeURIComponent(segmentId)}/review`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({review_status:status,review_notes:reviewNotes})});updateDirectorPromptDetail(out);note(status==='approved'?`${segmentId} 이미지를 승인했습니다.`:`${segmentId} 이미지를 수정 필요로 표시했습니다.`)}
function bindDirectorPromptSegmentControls(){document.querySelectorAll('[data-director-drop]').forEach(zone=>{const input=zone.querySelector('input');zone.onclick=()=>input.click();input.onchange=()=>{const file=input.files?.[0];if(file)uploadDirectorPromptSegmentImage(zone.dataset.directorDrop,file).catch(error=>note(error.message,true))};for(const event of ['dragenter','dragover'])zone.addEventListener(event,e=>{e.preventDefault();zone.style.borderColor='var(--accent)'});for(const event of ['dragleave','drop'])zone.addEventListener(event,e=>{e.preventDefault();zone.style.borderColor=''});zone.addEventListener('drop',e=>{const file=e.dataTransfer.files?.[0];if(file)uploadDirectorPromptSegmentImage(zone.dataset.directorDrop,file).catch(error=>note(error.message,true))})});document.querySelectorAll('[data-director-review]').forEach(button=>button.onclick=()=>reviewDirectorPromptSegmentImage(button.dataset.segment,button.dataset.directorReview).catch(error=>note(error.message,true)))}
async function selectDirectorPromptClip(clipId){try{const projectId=$('#directorPromptProject').value;const detail=prepareDirectorPromptDetail(await api(`/api/director-prompt-projects/${encodeURIComponent(projectId)}/clips/${encodeURIComponent(clipId)}`));directorPromptState.selectedDetail=detail;renderDirectorPromptDetail(detail)}catch(error){note(error.message,true)}}
async function loadDirectorPromptClips(){const projectId=$('#directorPromptProject').value;if(!projectId){directorPromptState.clips=[];directorPromptState.backgroundGroups=[];directorPromptState.selectedBackgroundId=null;renderDirectorPromptClips();return}const out=await api(`/api/director-prompt-projects/${encodeURIComponent(projectId)}/overview`);directorPromptState.clips=out.clips||[];directorPromptState.backgroundGroups=out.background_groups||[];directorPromptState.selectedBackgroundId=null;directorPromptState.selectedDetail=null;renderDirectorPromptClips();renderDirectorPromptDetail(null)}
async function loadDirectorPromptProjects(){const out=await api('/api/director-prompt-projects');directorPromptState.projects=out.projects||[];const select=$('#directorPromptProject');select.innerHTML=directorPromptState.projects.length?directorPromptState.projects.map(project=>`<option value="${directorPromptEscape(project.project_id)}">${directorPromptEscape(project.title)} · 준비 ${project.ready_count||0}/${project.clip_count||0}</option>`).join(''):'<option value="">프로젝트 없음</option>';await loadDirectorPromptClips()}
async function applyDirectorPromptClip(){const detail=directorPromptState.selectedDetail;if(!detail?.can_register_director)throw Error(detail?.registration_block_reason||'Director 등록 준비가 완료되지 않았습니다.');if(files.length&&!confirm('현재 01 생성 장면을 Director 프로젝트 내용으로 교체할까요?'))return;const payload=detail.machine_payload||{},segments=[...(payload.segments||[])].sort((a,b)=>Number(a.order||0)-Number(b.order||0)),loaded=[];for(const segment of segments){const image=segment.scene_image||{};if(!image.asset_url)throw Error(`${segment.segment_id}: 승인된 장면 이미지가 없습니다.`);const blob=await apiBlob(image.asset_url),name=String(image.source_path||image.suggested_filename||`${segment.segment_id}.png`).split('/').pop();loaded.push(new File([blob],name,{type:blob.type||'image/png'}))}files=loaded;renderSegments();const rows=$$('.segment');segments.forEach((segment,index)=>{const row=rows[index];if(!row)return;row.querySelector('.segment-prompt').value=segment.director_prompt||'';row.querySelector('.segment-seconds').value=String(Number(segment.seconds)||5);row.querySelector('.segment-order').value=String(Number(segment.order)||index+1)});const form=$('#createForm'),resolution=payload.resolution||{};form.elements.job_name.value=payload.clip_id||'LTX_scene';form.elements.fps.value=String(payload.fps||24);form.elements.global_prompt.value=payload.global_prompt||'';const value=`${resolution.width||1536}x${resolution.height||864}`;if([...form.elements.resolution.options].some(option=>option.value===value))form.elements.resolution.value=value;saveDraft();scheduleSeedRecommend();note(`Director 프롬프트를 01 생성에 불러왔습니다: ${payload.clip_id}`)}
function initDirectorPromptPanel(){const form=$('#createForm'),panel=document.createElement('details');panel.id='directorPromptPanel';panel.className='panel director-prompt-panel';panel.innerHTML=`<summary><div><h3>저장된 Director 프롬프트</h3><p class="muted">검수 승인된 장면 이미지와 Prompt Relay를 01 생성에 불러옵니다.</p></div></summary><div class="director-prompt-toolbar"><label>프로젝트<select id="directorPromptProject"></select></label><button type="button" id="directorPromptRefresh">새로고침</button></div><div id="directorPromptClips" class="director-prompt-clips muted">불러오는 중…</div><div id="directorPromptPreview" class="director-prompt-preview"><span class="muted">클립을 선택하세요.</span></div><button type="button" id="directorPromptLoad" class="primary alt" disabled>01 생성으로 불러오기</button>`;form.parentNode.insertBefore(panel,form);$('#directorPromptProject').onchange=()=>loadDirectorPromptClips().catch(error=>note(error.message,true));$('#directorPromptRefresh').onclick=()=>loadDirectorPromptProjects().catch(error=>note(error.message,true));$('#directorPromptLoad').onclick=()=>applyDirectorPromptClip().catch(error=>note(error.message,true));loadDirectorPromptProjects().catch(error=>{$('#directorPromptClips').textContent=error.message})}
const directorPromptStyle=document.createElement('style');directorPromptStyle.textContent='.director-prompt-panel{display:grid;gap:14px}.director-prompt-panel>summary{cursor:pointer}.director-prompt-toolbar{display:flex;gap:12px;align-items:end}.director-prompt-toolbar label{flex:1}.director-prompt-clips{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px}.director-prompt-clip{display:grid;gap:5px;text-align:left}.director-prompt-clip span,.director-prompt-clip small{font-size:11px;color:var(--muted)}.director-prompt-preview{display:grid;gap:10px}.director-prompt-meta{display:flex;gap:12px;flex-wrap:wrap}.director-prompt-preview pre{white-space:pre-wrap;max-height:220px;overflow:auto}.director-prompt-segments{display:grid;gap:12px}.director-prompt-segments article{display:grid;grid-template-columns:180px 1fr;gap:12px;border:1px solid var(--line);border-radius:10px;padding:10px}.director-prompt-segments img,.director-prompt-image-missing{width:180px;aspect-ratio:16/9;object-fit:cover;border-radius:8px;background:#0b111a}.director-prompt-image-missing{display:grid;place-items:center;color:var(--muted)}.director-prompt-segments section{display:grid;gap:6px}.director-prompt-segments p{white-space:pre-wrap;margin:0}.director-prompt-warning{color:#ffe1a3}@media(max-width:700px){.director-prompt-segments article{grid-template-columns:1fr}.director-prompt-segments img,.director-prompt-image-missing{width:100%}}';document.head.append(directorPromptStyle);initDirectorPromptPanel();
const directorPromptCss=document.createElement('link');directorPromptCss.rel='stylesheet';directorPromptCss.href='/director-prompts.css?v=20260729-1';document.head.append(directorPromptCss);
const directorBackgroundAccordionCss=document.createElement('link');directorBackgroundAccordionCss.rel='stylesheet';directorBackgroundAccordionCss.href='/director-background-accordion.css?v=20260729-2';document.head.append(directorBackgroundAccordionCss);
const msrDraft=JSON.parse(localStorage.getItem('ltx-msr-v2-draft')||'{}');
const msrEscape=value=>String(value??'').replace(/[&<>\"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[char]));
const msrFileInputs=[1,2,3,4].map(index=>$(`#msrRef${index}`));
const msrDroppedFiles=new Map();
const msrPromptState={projects:[],clips:[],backgrounds:[],backgroundLinks:{},selectedProjectId:msrDraft.prompt_project_id||'RaisingaDragonSeason01',selectedClipId:msrDraft.prompt_clip_id||'',selectedDetail:null};
let msrLoadedPromptStatus='';
let msrLoadedBackgroundReviewStatus='';
let msrRelaySegments=Array.isArray(msrDraft.relay_segments)&&msrDraft.relay_segments.length?msrDraft.relay_segments:[{prompt:'',seconds:5},{prompt:'',seconds:5}];
let msrLoadedPromptSources={references:[],background:null,prompt_project_id:'',prompt_clip_id:'',reference_mode:'subject_references'};
const msrSelectedFile=input=>input.files?.[0]||msrDroppedFiles.get(input)||null;
const isMsrImage=file=>file?.type?.startsWith('image/')||/\.(png|jpe?g|jfif|webp)$/i.test(file?.name||'');
function setMsrInputFile(input,file){msrDroppedFiles.set(input,file);try{const transfer=new DataTransfer();transfer.items.add(file);input.files=transfer.files}catch{}input.dispatchEvent(new Event('change',{bubbles:true}))}
function updateMsrDropLabel(input){const zone=input.closest('label');let status=zone.querySelector('.msr-file-status');if(!status){status=document.createElement('small');status.className='msr-file-status';zone.insertBefore(status,zone.querySelector('textarea'))}const file=msrSelectedFile(input);status.textContent=file?.name||'클릭하거나 이미지를 드롭하세요.';zone.classList.toggle('has-file',!!file)}
function fillMsrReferenceFiles(startIndex,files){let cursor=0;for(let index=startIndex;index<msrFileInputs.length&&cursor<files.length;index++){const input=msrFileInputs[index];if(index===startIndex||!msrSelectedFile(input))setMsrInputFile(input,files[cursor++])}}
function bindMsrDropZone(input,index=null){const zone=input.closest('label');zone.classList.add('msr-drop-zone');input.addEventListener('change',()=>{if(input.files?.[0])msrDroppedFiles.set(input,input.files[0]);updateMsrDropLabel(input)});for(const type of ['dragenter','dragover'])zone.addEventListener(type,event=>{event.preventDefault();event.stopPropagation();zone.classList.add('dragging')});for(const type of ['dragleave','drop'])zone.addEventListener(type,event=>{event.preventDefault();event.stopPropagation();zone.classList.remove('dragging')});zone.addEventListener('drop',event=>{const images=[...event.dataTransfer.files].filter(isMsrImage);if(!images.length)return;if(index===null)setMsrInputFile(input,images[0]);else fillMsrReferenceFiles(index,images)});updateMsrDropLabel(input)}
msrFileInputs.forEach((input,index)=>bindMsrDropZone(input,index));bindMsrDropZone($('#msrBackground'));
function compileMsrGlobalPreview(){const form=$('#msrForm'),world=String(form?.elements.world_prompt?.value||'').trim(),lines=world?[world]:[],anchorMode=msrLoadedPromptSources.reference_mode==='anchor_as_reference';for(let slot=1;slot<=4;slot++){const description=String($(`#msrRefDesc${slot}`)?.value||'').trim();if(description)lines.push(`Picture ${slot} — ${anchorMode&&slot===1?'Scene Anchor':(slot<=2?'Character':'Prop')}: ${description}`)}if(String($('#msrRefDesc2')?.value||'').trim())lines.push('Keep Picture 1 and Picture 2 visually distinct; never merge their identity, anatomy or costume.');if([3,4].some(slot=>String($(`#msrRefDesc${slot}`)?.value||'').trim()))lines.push('Pictures 3 and 4 are objects only; keep their owner, shape and material consistent and never turn them into characters.');return lines.join('\n')}
function updateMsrComposer(){const total=msrRelaySegments.reduce((sum,item)=>sum+(Number(item.seconds)||0),0),meta=$('#msrTotalDuration'),preview=$('#msrGlobalPreview');if(meta){meta.textContent=`현재 ${total.toFixed(2)}초 / 20초`;meta.classList.toggle('error',total>20)}if(preview)preview.value=compileMsrGlobalPreview()}
function saveMsrDraft(){const form=new FormData($('#msrForm'));localStorage.setItem('ltx-msr-v2-draft',JSON.stringify({job_name:form.get('job_name'),source_scene_refs:form.get('source_scene_refs'),continuity_mode:form.get('continuity_mode'),seed:form.get('seed'),resolution:form.get('resolution'),world_prompt:form.get('world_prompt'),candidate_count:form.get('candidate_count'),prompt_strategy:'msr_continuity_v1',reference_descriptions:[1,2,3,4].map(slot=>$(`#msrRefDesc${slot}`).value),anchor_description:$('#msrBackgroundDesc').value,relay_segments:msrRelaySegments,prompt_project_id:msrPromptState.selectedProjectId||'',prompt_clip_id:msrPromptState.selectedClipId||'',prompt_reference_sources:msrLoadedPromptSources.references,prompt_background_source:msrLoadedPromptSources.background,reference_mode:msrLoadedPromptSources.reference_mode||'subject_references',prompt_status:msrLoadedPromptStatus||'',background_review_status:msrLoadedBackgroundReviewStatus||''}));updateMsrComposer()}
