function modelTestAiReviewStatus(run){
 const status=String(run.ai_review_status||'not_started');
 const labels={not_started:'AI 미검수',queued:'AI 검수 대기',preparing:'AI 준비 중',reviewing:'AI 검수 중',completed:'AI 검수 완료',failed:'AI 검수 실패'};
 const order=run.ai_review_order==null?'':` · #${Number(run.ai_review_order)+1}`;
 return `<span class="model-test-ai-state ai-${esc(status)}">${esc(labels[status]||status)}${order}</span>`;
}
function modelTestReviewSummaries(run){
 const rows=[[(String(run.ai_review?.rubric_version||'').startsWith('r2v_')?'R2V 전용 AI 검수':'Qwen 자동 검수'),run.ai_review],["사람 검수",run.human_review]].filter(([,review])=>review);
 if(!rows.length)return '<p class="muted">아직 저장된 리뷰가 없습니다.</p>';
 return rows.map(([label,review])=>{
  const checks=review.event_checks||[],forbidden=review.forbidden_checks||[],references=review.reference_checks||[],dialogue=review.dialogue_checks||[],bindings=review.subject_binding_checks||[],shot=review.shot_structure_check||{},gate=review.enforcement||{};
  const confidence=review.confidence==null?'':` · 신뢰도 ${Math.round(Number(review.confidence)*100)}%`,strict=review.rubric_version==='strict_prompt_compliance_v2';
  const r2v=String(review.rubric_version||'').startsWith('r2v_'),generalV5=review.rubric_version==='r2v_general_reference_grounded_v5',storyboardV4=review.rubric_version==='r2v_multishot_storyboard_dialogue_grounded_v4',storyboardV3=review.rubric_version==='r2v_storyboard_dialogue_grounded_v3',storyboardV2=storyboardV4||storyboardV3||review.rubric_version==='r2v_storyboard_grounded_v2';
  const referenceRows=references.map(item=>`<li><strong>Picture ${esc(item.picture_index)} · ${esc(item.status||'uncertain')}</strong> · ${esc(item.label_ko||item.role||'')}<small>${esc(item.evidence_ko||'')}</small>${(item.panel_beat_checks||[]).length?`<ul>${item.panel_beat_checks.map(panel=>`<li>${storyboardV4?'Shot':'패널'} ${esc(panel.shot_index||panel.panel_index)} · <strong>${esc(panel.status)}</strong><small>${esc(panel.evidence_ko||'')}</small></li>`).join('')}</ul>`:''}</li>`).join('');
  const dialogueRows=dialogue.map(item=>`<li><strong>${esc(item.speaker_id||item.speaker)} · ${esc(item.line_ko||'')}</strong><small>대사 ${esc(item.exact_text_status)} · 화자 ${esc(item.speaker_identity_status)} · 순서 ${esc(item.order_status)} · 립싱크 ${esc(item.lip_sync_status)} · 비화자 입 ${esc(item.non_speaker_mouth_status)} · ${esc(item.evidence_ko||'')}</small></li>`).join('');
  const bindingRows=bindings.map(item=>`<li><strong>Subject ${esc(item.subject_index)} · Picture ${esc(item.picture_index)} · ${esc(item.status)}</strong><small>${esc(item.label_ko||item.role||'')} · ${esc(item.evidence_ko||'')}</small></li>`).join('');
  const shotRow=Object.keys(shot).length?(generalV5?`<div class="model-test-event-checks"><b>일반 숏 구조·카메라</b><p>샷 수·순서 ${esc(shot.shot_count_order_status)} · 컷 타이밍 ${esc(shot.cut_timing_status)} · 화면 방향 ${esc(shot.screen_direction_status)} · 카메라 ${esc(shot.camera_plan_status)}</p><small>${esc(shot.evidence_ko||'')}</small></div>`:storyboardV4?`<div class="model-test-event-checks"><b>멀티샷 구조·카메라·레이아웃</b><p>샷 수·순서 ${esc(shot.shot_count_order_status)} · 컷 타이밍 ${esc(shot.cut_timing_status)} · 화면 방향 ${esc(shot.screen_direction_status)} · 카메라 ${esc(shot.camera_plan_status)} · 패널 화면 누출 ${esc(shot.storyboard_layout_leak)}</p><small>${esc(shot.evidence_ko||'')}</small></div>`:`<div class="model-test-event-checks"><b>연속 샷·카메라·레이아웃</b><p>연속 샷 ${esc(shot.continuous_shot_status)} · 화면 방향 ${esc(shot.screen_direction_status)} · 카메라 ${esc(shot.camera_plan_status)} · 패널 화면 누출 ${esc(shot.storyboard_layout_leak)}</p><small>${esc(shot.evidence_ko||'')}</small></div>`):'';
  return `<section class="model-test-review-source"><b>${label} · ${esc(review.verdict)} · revision ${review.revision} · 문제 ${(review.issues||[]).length}건${confidence}</b>${strict?`<p><strong>엄격 프롬프트 게이트 v2 · ${gate.gate_passed?'통과':'미통과'}</strong> · 필수 행동 ${esc(gate.required_verified||0)}/${esc(gate.required_total||0)} · 금지 실패 관찰 ${esc(gate.forbidden_observed||0)} · 불확실 ${esc(gate.forbidden_uncertain||0)}</p>`:''}${r2v?`<p><strong>${generalV5?'R2V 공통 참조·프롬프트 게이트 v5':storyboardV4?'R2V 멀티샷·대사 게이트 v4':storyboardV3?'R2V 스토리보드·대사 게이트 v3':storyboardV2?'R2V 멀티패널 스토리보드 게이트 v2':'R2V 참조 기반 게이트 v1'} · ${gate.gate_passed?'통과':'미통과'}</strong> · 참조 일치 ${esc(gate.reference_matched||0)}/${esc(gate.reference_total||0)}${storyboardV2?` · 스토리보드 샷 ${esc(gate.storyboard_shot_verified??gate.storyboard_panel_verified??0)}/${esc(gate.storyboard_shot_total??gate.storyboard_panel_total??0)}`:''}${generalV5||storyboardV4||storyboardV3?` · 대사 모순 ${esc(gate.dialogue_hard_contradicted||0)} · Subject 모순 ${esc(gate.subject_binding_major_mismatch||0)}`:''} · 사람 확인 ${gate.human_review_required?'필요':'불필요'}</p>`:''}<p>${esc(review.overall_note||'메모 없음')}</p><div class="model-test-score-summary">${Object.entries(review.scores||{}).map(([key,value])=>`<span><b>${esc(modelTestActiveResults.score_dimensions[key]||key)}</b>${Number(value).toFixed(1)}</span>`).join('')}</div>${references.length?`<div class="model-test-event-checks"><b>참조 이미지 판정</b><ul>${referenceRows}</ul></div>`:''}${bindings.length?`<div class="model-test-event-checks"><b>Subject 역할 바인딩</b><ul>${bindingRows}</ul></div>`:''}${dialogue.length?`<div class="model-test-event-checks"><b>화자·대사·립싱크</b><ul>${dialogueRows}</ul></div>`:''}${shotRow}${checks.length?`<div class="model-test-event-checks"><b>필수 사건 판정</b><ul>${checks.map(item=>`<li><strong>${esc(item.status||'uncertain')}</strong> · ${esc(item.requirement_ko||'')}<small>${esc(item.evidence_ko||'')}</small></li>`).join('')}</ul></div>`:''}${forbidden.length?`<div class="model-test-event-checks"><b>금지 실패 판정</b><ul>${forbidden.map(item=>`<li><strong>${esc(item.status||'uncertain')}</strong> · ${esc(item.failure_ko||'')}<small>${esc(item.evidence_ko||'')}</small></li>`).join('')}</ul></div>`:''}</section>`;
 }).join('');
}
